from mk9 import M4, build
def fm(x):
    x = F(x)
    return str(x.numerator) if x.denominator == 1 else f"{float(x):.2f}".rstrip("0").rstrip(".")
A = []
# generated concentration MCQs (8)
for sol, sv, kind in [(10, 90, "m/m"), (20, 80, "m/m"), (6, 34, "m/m"), (12, 88, "m/m")]:
    tot = sol + sv; p = F(sol*100, tot)
    A.append(M4(f"{sol} g of salt is dissolved in {sv} g of water. The mass by mass percentage of the solution is:", f"{fm(p)} %", [f"{fm(F(sol*100, sv))} %", f"{fm(p/2)} %", f"{fm(p+10)} %"], f"$\\frac{{{sol}}}{{{tot}}}\\times100={fm(p)}$"))
for g, ml in [(5, 100), (9, 1000), (2, 50), (18, 200)]:
    p = F(g*100, ml)
    A.append(M4(f"{g} g of a solute is dissolved in water to make {ml} mL of solution. Its mass by volume percentage (% m/v) is:", f"{fm(p)} %", [f"{fm(F(g*100, ml+g))} %", f"{fm(p*2)} %", f"{fm(p/2)} %"], f"$\\frac{{{g}}}{{{ml}}}\\times100={fm(p)}$"))
